mapper.select:
SELECT bi.*, u.user_name, u.avatar, u.phone, (SELECT COUNT(*) FROM travel_collect WHERE type = 3 AND data_id = bi.id) as collectCount FROM travel_base_info bi LEFT JOIN tb_user u ON bi.user_id = u.user_id
and bi.title like concat('%', #{param.title} ,'%')
and bi.userId = #{param.userId}
and bi.status = #{param.status}
order by bi.create_time desc
